function gh($method,$url,$payload=null){$t=getenv('GITHUB_TOKEN')?:'';if(!$t)throw new Exception('GITHUB_TOKEN belum diatur di Vercel.');$o=['http'=>['method'=>$method,'ignore_errors'=>true,'header'=>"Authorization: Bearer $t\r\nAccept: application/vnd.github+json\r\nX-GitHub-Api-Version: 2022-11-28\r\nUser-Agent: Bebanklan-CMS\r\nContent-Type: application/json",'timeout'=>20]];if($payload!==null)$o['http']['content']=json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$ctx=stream_context_create($o);$fp=@fopen($url,'rb',false,$ctx);$b='';$headers=[];if($fp!==false){$b=stream_get_contents($fp)?:'';$meta=stream_get_meta_data($fp);$headers=$meta['wrapper_data']??[];fclose($fp);} $s=0;foreach($headers as $line){if(is_string($line)&&preg_match('/^HTTP\/\S+\s+(\d{3})\b/',$line,$m)){$s=(int)$m[1];}}$j=$b?json_decode($b,true):null;if($s<200||$s>=300)throw new Exception((is_array($j)?($j['message']??'GitHub error'):'GitHub error').' (HTTP '.$s.')');return is_array($j)?$j:[];}
function repo(){return getenv('GITHUB_REPO')?:'josuavndev/clashofclanbebanklan-bio';}
function put($path,$content,$message,$sha=null){$u='https://api.github.com/repos/'.repo().'/contents/'.str_replace('%2F','/',rawurlencode($path));$p=['message'=>$message,'content'=>base64_encode($content),'branch'=>'main'];if($sha)$p['sha']=$sha;gh('PUT',$u,$p);}
