function uploadImg($field){if(!isset($_FILES[$field])||($_FILES[$field]['error']??4)===4)return null;$f=$_FILES[$field];if($f['error']!==0)throw new Exception('Upload gambar gagal.');if($f['size']>5242880)throw new Exception('Gambar maksimal 5 MB.');$e=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));if(!in_array($e,['jpg','jpeg','png','webp','gif','svg'],true))throw new Exception('Format gambar: JPG, PNG, WEBP, GIF, SVG.');$base=preg_replace('/[^a-zA-Z0-9_-]+/','-',pathinfo($f['name'],PATHINFO_FILENAME));$n=$base.'-'.substr(bin2hex(random_bytes(4)),0,8).'.'.$e;put('public/uploads/'.$n,file_get_contents($f['tmp_name']),'Upload CMS image');return'/uploads/'.$n;}
