ne}.preview.show{display:block}@media(max-width:700px){body{padding:12px}.grid{grid-template-columns:1fr}.full{grid-column:auto}.top{align-items:flex-start}.brand{font-size:21px}.actions{flex-wrap:wrap}}</style>';}
