function productCard($p,$i){$img=!empty($p['imageUrl'])?'<img class="thumb preview show" src="'.h($p['imageUrl']).'">':'';return '<div class="card"><div class="head"><b>Produk #'.($i+1).'</b><button type="button" class="del" onclick="this.closest(\'.card\').remove()">HAPUS</button></div><div class="grid"><div><label>Nama</label>'.in("products[$i][name]",$p['name']??'','text','required').'</div><div><label>Harga</label>'.in("products[$i][price]",$p['price']??'').'</div><div class="full"><label>Deskripsi</label>'.area("products[$i][description]",$p['description']??'').'</div><div><label>Rarity</label>'.in("products[$i][rarity]",$p['rarity']??'').'</div><div><label>Status</label><select name="products['.$i.'][status]"><option '.(($p['status']??'')==='READY STOCK'?'selected':'').'>READY STOCK</option><option '.(($p['status']??'')==='SOLD OUT'?'selected':'').'>SOLD OUT</option></select></div><div><label>Icon Type</label>'.in("products[$i][iconType]",$p['iconType']??'gem-pouch').'</div><div><label>Featured</label><input type="checkbox" name="products[$i][featured]" '.(!empty($p['featured'])?'checked':'').'></div><div class="full upload"><label>Gambar Produk</label><input type="file" name="product_images['.$i.']" accept="image/*" onchange="previewFile(this)"><div class="hint">Pilih gambar langsung. Maks 5 MB. Tidak ada JSON atau URL gambar.</div>'.$img.'</div></div></div>';}
