<label>Harga</label><input name="products[${i}][price]"></div><div class="full"><label>Deskripsi</label><textarea name="products[${i}][description]"></textarea></div><div><label>Rarity</label><input name="products[${i}][rarity]"></div><div><label>Status</label><select name="products[${i}][status]"><option>READY STOCK</option><option>SOLD OUT</option></select></div><div><label>Icon Type</label><input name="products[${i}][iconType]" value="gem-pouch"></div><div><label>Featured</label><input type="checkbox" name="products[${i}][featured]"></div><div class="full upload"><label>Gambar Produk</label><input type="file" name="product_images[${i}]" accept="image/*" onchange="previewFile(this)"><div class="hint">Upload langsung. Maks 5 MB.</div></div></div></div>`)}function addDonor(g){let b=document.getElementById(g),i=b.children.length,f=g==="monthly"?"monthly_images":"alltime_images",title=g==="monthly"?"Donatur Bulanan":"Donatur All Time";b.insertAdjacentHTML("beforeend",`<div class="card"><div class="head"><b>${title} #${i+1}</b><button type="button" class="del" onclick="this.closest(\'.card\').remove()">HAPUS</button></div><div class="grid"><div><label>Rank</label><input type="number" min="1" value="${i+1}" name="${g}[${i}][rank]"></div><div><label>Nama</label><input required name="${g}[${i}][name]"></div><div><label>Amount</label><input name="${g}[${i}][amount]"></div><div><label>Coffee</label><input name="${g}[${i}][coffee]"></div><div><label>Tier</label><input name="${g}[${i}][tier]"></div><div><label>Avatar Background</label><input name="${g}[${i}][avatarBg]"></div><div class="full"><label>Catatan</label><textarea name="${g}[${i}][note]"></textarea></div><div class="full upload"><label>Foto Donatur</label><input type="file" name="${f}[${i}]" accept="image/*" onchange="previewFile(this)"><div class="hint">Upload langsung. Tidak perlu URL/path.</div></div></div></div>`)}</script></body></html>';
